import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Statements;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
 * figure its last statement bound it to, else its amount times the rate in force on the claim's date of its
 * person's grade in force on that date (rounded as the claim rounds by the sheet's policy date, and at least the sheet's floor in force on the claim's date; none without a rate). The due-total is the counting claims' figures
 * added up, each with its late charge on top while it is overdue (the charge is never bound); n/a
 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure; at most the sheet's cap in force on its today.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, StatementRepository statements, Out<Statement> taken) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        List<Claim> mine = claims.listOf(sheetId, person.getId());
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        for (Claim c : mine) {
            // OPEN and PENDING claims dated within a hold do not count, unless the last statement bound them.
            if (!c.getStatus().counts() || Rollup.held(c, person)) {
                claims.bind(c.getId(), false, null);
                continue;
            }
            counted++;
            kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
            BigDecimal figure = figure(c, person, rates, late);
            // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
            // dated on or before today, whose rate may have ended since.
            kept |= figure != null && (!person.gradeOn(c.getDate()).equals(person.getGrade()) || !c.getDate().isAfter(today));
            if (figure != null) {
                sum = sum.add(late.due(c, figure));
            }
            claims.bind(c.getId(), true, figure);
        }
        BigDecimal dueTotal = SettingRepository.capped(
                kept || rates.find(sheetId, person.getGrade(), today) != null ? sum : null, late.settings().cap(today));
        statements.insert(sheetId, person.getId(), dueTotal, today);
        person.setStatements(new Statements(person.getStatements().count() + 1, dueTotal, today));
        taken.set(new Statement(dueTotal, counted));
    }

    private static BigDecimal figure(Claim claim, Person person, RateRepository rates, LateCharge late) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        BigDecimal rate = rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        return claim.figureAt(rate, late.settings().floor(claim.getDate()), late.rounding(claim));
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;

/**
 * The late charge as of the sheet's today: an OPEN (or PENDING) claim past its due-by (fixed when it was added) gains the late
 * percent in force on its date of its figure for every full 30 days it is overdue, rounded to two decimals as the claim rounds (see
 * {@link #rounding}). A correction
 * (a negative amount) never gains one. The charge is never bound by a statement; settling freezes it into the settled due.
 */
public record LateCharge(LocalDate today, DatedSettings settings, LocalDate policyDate) {

    /**
     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after
     * it. A correction rounds by the date of the claim it corrects.
     */
    public RoundingMode rounding(Claim claim) {
        return claim.getRoundOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The claim's late charge on its figure (zero when it is not overdue, or has no figure). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (!claim.getStatus().isOpen()) {
            return none;
        }
        return onAsOpen(claim, figure);
    }

    /** The late charge the claim would have on its figure were it OPEN. */
    public BigDecimal onAsOpen(Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.isCorrection()) {
            return none;
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        if (periods == 0) {
            return none;
        }
        return figure.multiply(settings.latePct(claim.getDate())).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(claim));
    }

    /** The figure with the claim's late charge added on top; null without a figure. */
    public BigDecimal due(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.setScale(2).add(on(claim, figure));
    }

    /** The figure with the late charge the claim would have were it OPEN; null without a figure. */
    public BigDecimal dueAsOpen(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.setScale(2).add(onAsOpen(claim, figure));
    }
}
-- Where a claim is listed: claims are listed newest first by this key, not by id, so a claim moved to
-- another person is listed as that person's newest. A claim takes the sheet's next key when it is
-- added or moved; the sheet keeps the last key it gave.
ALTER TABLE sheet ADD COLUMN last_claim_listed BIGINT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
UPDATE sheet SET last_claim_listed = COALESCE((SELECT MAX(c.id) FROM claim c WHERE c.sheet_id = sheet.id), 0);
CREATE INDEX claim_listed ON claim (sheet_id, person_id, listed);
-- A claim's due-by is fixed when it is added: its date plus the terms of its person's grade in force on that date
-- (the grade's own terms, setting terms-<grade>, else the sheet's terms). Later changes to the terms or to the claim's
-- date leave it as it is. Existing claims take their date plus the sheet's terms (14 until they are set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM sheet_setting s
    WHERE s.sheet_id = claim.sheet_id AND s.setting_key = 'terms'), 14), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A claim's status log: one line per status it has had, in the order it had them (by id) — who made the change, the
-- sheet's today then, and the claim's due as computed at that moment (null: n/a). Its DRAFT line is written when it is added.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)    NOT NULL,
    by_user   VARCHAR(200)   NOT NULL,
    logged_on DATE           NOT NULL,
    due       DECIMAL(14, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
-- A person may have several holds over time, each from its from-date to its to-date (null: open-ended), both
-- inclusive. A hold leaves out of the live totals only the person's OPEN and PENDING claims dated within it that no
-- statement binds. A person held before keeps a hold from the beginning of time (null from-date).
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id, id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate can carry a to-date: it applies through that date (null: with no end). A claim dated after
-- the to-date of the rate that would apply to it, with no later rate in force then, has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- Closing a period also fixes each person's due-total for it, for every person on the sheet at that moment
-- (a person added later has none: 0.00). The period's closed_total is the sum of these. Reopening removes them.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The settings that carry a figure (the floor, the late percent, the terms and each grade's, the clerk limit, the cap)
-- are dated: each value is in force from its from-date until the next one's. A null value is blank. A value already
-- set before settings were dated is kept as in force from the beginning of time.
CREATE TABLE sheet_setting_from (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(50)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);

INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');

DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');

