function SheetTodayPanel({ sheetId }: { sheetId: string; user: string }) {
  const today = useSheetToday(sheetId);
  const [input, setInput] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: async (date: string) => {
      if (date.trim() === '') throw new Error('Enter a date');
      return putJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today: date.trim(), by: user ?? '' });
    },
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetTodayKey(sheetId), saved);
      await queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'today',
      });
    },
  });

  const submit = useSubmitOnce(save);
  return (
    <section data-testid="sheet-today-panel">
      <p>
        Today: <strong data-testid="sheet-today">{today.data?.today ?? ''}</strong>
      </p>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submit(input);
        }}
      >
        <input
          type="date"
          data-testid="sheet-today-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            save.reset();
          }}
        />{' '}
        <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
          Set today
        </button>
      </form>
      {(save.isError || today.isError) && (
        <p data-testid="sheet-error" role="alert">
          {(save.error ?? today.error)?.message}
        </p>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 0, Component: SheetTodayPanel });
  return (
    <>
      <th>Claimed</th>
      <th>Claims</th>
    </>
  );
}

// A person's claimed total, and their claims, newest first, under the form that adds or edits them.
function ClaimsCells({ sheetId, user, personId }: { sheetId: string; user: string; personId: number }) {
  const claims = useClaims(sheetId);
  const [editingId, setEditing] = useEditingClaim();
  const held = useHeld(sheetId);
  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
  const editing = mine.find((c) => c.id === editingId);

  return (
    <>
      <td data-testid="person-claimed">{sumAmounts(mine, held)}</td>
      <td>
        <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheetId={sheetId} personId={personId} editing={editing} />
        <ul data-testid="claim-list">
          {mine.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <span data-testid="claim-amount">{Number(c.amount).toFixed(2)}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
              <ClaimCells.Slot sheetId={sheetId} user={user} personId={personId} claim={c} />
              {editing?.id === c.id ? (
                <button type="button" data-testid="claim-cancel" onClick={() => setEditing(undefined)}>
